import {readFileSync,writeFileSync} from 'node:fs';import {createRequire} from 'node:module';
const path=process.argv[2],r=JSON.parse(readFileSync(path,'utf8'));const prepared=r.report.prepared,model=prepared.candidate.model,Q=prepared.candidate.currentBasis,R=prepared.cellResistanceOhm;
const addon=createRequire(import.meta.url)('../../../native/node-addon/index.cjs'),session=new addon.AnalysisElectricalSession();
const dotR=(a:number[],b:number[])=>a.reduce((sum,x,j)=>sum+x*R[Math.floor(j/3)]*b[j],0);let orthogonalityError=0;for(let i=0;i<Q.length;i++)for(let j=0;j<Q.length;j++)orthogonalityError=Math.max(orthogonalityError,Math.abs(dotR(Q[i],Q[j])-(i===j?1:0)));if(orthogonalityError>1e-8)throw Error('CURRENT_BASIS_NOT_R_ORTHONORMAL');
const axis=[0,1000,1700,Math.sqrt(1e7),6300,10000],states=[];let reconstructionError=0;
for(const drive of [[1,0,-1,0],[0,1,0,-1]]){
 const response=session.solveLocal({prepared,frequenciesHz:axis,drive,loadsOhm:[50,50,50,50]},30,false);
 const samples=response.samples.map((sample:any)=>{const parts=[0,1].map(k=>sample.currentRealImaginaryA.map((v:number[])=>v[k]));const q=parts.map(J=>Q.map((v:number[])=>dotR(v,J)));
  for(let k=0;k<2;k++){const J=parts[k],difference=J.map((x,j)=>x-Q.reduce((sum:number,v:number[],i:number)=>sum+v[j]*q[k][i],0));reconstructionError=Math.max(reconstructionError,Math.sqrt(Math.abs(dotR(difference,difference)))/Math.max(1e-30,Math.sqrt(Math.abs(dotR(J,J)))));}
  const magneticMeanEnergyJ=model.inductanceH.reduce((sum:number,[i,j,v]:number[])=>sum+.5*v*(q[0][i]*q[0][j]+q[1][i]*q[1][j]),0);return {...sample,currentRealImaginaryA:undefined,cellLossW:undefined,q,magneticMeanEnergyJ};});states.push({drive,samples});
}
if(reconstructionError>1e-8)throw Error('CURRENT_PROJECTION_LOSS');
const returnCells=prepared.sourceIds.map((ids:string[],cell:number)=>({ids,cell})).filter((v:any)=>v.ids.some((id:string)=>prepared.mapping.some((m:any[])=>m[0]===id&&m[3]==='BOTTOM')));const physical=session.solveLocal({prepared,frequenciesHz:[1000],drive:[1,0,-1,0],loadsOhm:[50,50,50,50]},30,false);const J=physical.samples[0].currentRealImaginaryA;const returnCurrentDensity=returnCells.map(({cell}:any)=>{const points=prepared.copperCells[cell].map((i:number)=>prepared.nodesM[i]),centre=[0,1].map(k=>points.reduce((s:number,p:number[])=>s+p[k],0)/4*1000+prepared.originMm[k]);return {atMm:centre,realAPerM2:[0,1,2].map(k=>J[3*cell+k][0]*prepared.cellDensityPerAmpM2[cell])};});
const projection=states.map(a=>states.map(b=>model.inductanceH.reduce((sum:number,[i,j,v]:number[])=>sum+v*a.samples[0].q[0][i]*b.samples[0].q[0][j],0)));
const reactiveH=axis.slice(1).map((f,k)=>[0,1].map(i=>[0,1].map(j=>{const v=states[j].samples[k+1].portImaginaryV;return (v[i]-v[i+2])/(2*Math.PI*f);})));const result={returnCurrentDensity,projectionH:projection,reactiveH,frequenciesHz:axis,orthogonalityError,reconstructionError,states,convention:'Actual native loaded AC1A balanced drive/current recovery; mean magnetic energy=.5(Re(i)^T L Re(i)+Im(i)^T L Im(i)). DC current projection retained separately, not a substitute for AC field extraction.'};writeFileSync(path.replace('.json','-magnetic.json'),JSON.stringify(result));console.log(JSON.stringify({projectionH:projection,orthogonalityError,reconstructionError}));
